package cli

// Legacy parity: dra-inspect JSON over the committed fixtures must yield the
// same FACTS the lab script dra-verify.sh / dra-counters.py produced over the
// same fixtures (testdata/parity/*.facts.json, regenerated by the manual tool
// hack/capture-legacy-facts.sh, never in CI).
//
// Covered: drivers (device and node counts), topology (device -> NUMA and
// pcieRoot), claims (allocated device list per claim), alignment (device list
// and aligned/split verdict category per pod), DeviceClass selection
// (positional filter -> --selector) and counters (remaining/total per set).
//
// Not covered, by design: slices, attributes (legacy output is column
// formatting only) and cpupinning, vfio, metadata, guest (they need a node,
// exec or SSH). `deviceclasses` needs Python >= 3.12, so only the names its
// kubectl query selected are compared, not its table.
//
// Intentional differences, so a green test does not mean identical output:
//   - cpuSocketID is ignored: it is not a standard attribute, the legacy socket
//     inference and "cpuSocketID SPLIT" verdict are gone.
//   - Legacy groups a device under its FIRST listed NUMA node; dra-inspect keeps
//     the whole sorted NUMA set. The test checks first-NUMA membership.
//   - Legacy alignment is per pod (reservedFor), dra-inspect's is per claim and
//     uses global intersection of the list values, not string equality.
//   - Legacy ignores allocated claims without reservedFor (counters, alignment);
//     dra-inspect counts every allocation. The fixture claims have none, so the
//     counters facts are captured twice: as-is and with a stub-injected
//     reservedFor. Remaining counts are compared with the injected variant.
//   - Legacy never fails an overcommitted counter (it prints -1/2 in red, exit 0)
//     and counts every ResourceSlice generation; dra-inspect fails overcommit
//     and uses the current pool generation only.
//   - dra-inspect checks every allocated claim, including unreserved ones and
//     one referencing a device absent from the slices (fail: data
//     inconsistency); legacy skips claims without reservedFor.
//   - Legacy prints "?/N" for a counter it cannot compute (unknown counter
//     name); dra-inspect fails the check instead.
//   - ANSI colors, ordering, column layout and selector text are not compared
//     (dra-inspect never prints CEL selectors or opaque parameters).

import (
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"testing"

	"github.com/johnahull/k8s-dra-inspect/internal/model"
	"github.com/johnahull/k8s-dra-inspect/internal/testutil"
)

type legacyFacts struct {
	Fixture string `json:"fixture"`
	Drivers map[string]struct {
		Devices int      `json:"devices"`
		Nodes   []string `json:"nodes"`
	} `json:"drivers"`
	Topology map[string]struct {
		PrimaryNuma string   `json:"primaryNuma"`
		PcieRoots   []string `json:"pcieRoots"`
	} `json:"topology"`
	Alignment map[string]struct {
		Devices  []string `json:"devices"`
		Numa     string   `json:"numa"`
		PcieRoot string   `json:"pcieRoot"`
	} `json:"alignment"`
	Claims               map[string][]string `json:"claims"`
	DeviceClassesQueried []string            `json:"deviceclassesQueried"`
	Counters             legacyCounters      `json:"counters"`
	CountersReserved     legacyCounters      `json:"countersWithReservedFor"`
}

type legacyCounters struct {
	Exit int                          `json:"exit"`
	Sets map[string]map[string]string `json:"sets"`
}

func loadFacts(t *testing.T, name string) legacyFacts {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("..", "..", "testdata", "parity", name+".facts.json"))
	if err != nil {
		t.Fatal(err)
	}
	var f legacyFacts
	if err := json.Unmarshal(data, &f); err != nil {
		t.Fatal(err)
	}
	return f
}

type jsonResult struct {
	Check   string         `json:"check"`
	Status  string         `json:"status"`
	Subject string         `json:"subject"`
	Details map[string]any `json:"details"`
}

func newResults(t *testing.T, snap model.Snapshot, args ...string) []jsonResult {
	t.Helper()
	out, _ := cmdRun(t, snap, append([]string{"-o", "json"}, args...)...)
	var env struct {
		Results []jsonResult `json:"results"`
	}
	if err := json.Unmarshal([]byte(out), &env); err != nil {
		t.Fatalf("%v\n%s", err, out)
	}
	return env.Results
}

func strs(v any) []string {
	var out []string
	for _, x := range v.([]any) {
		out = append(out, x.(string))
	}
	return out
}

var surfaceFixtures = []string{"xe9785l", "xe9680", "classes-claims"}

func TestParityDrivers(t *testing.T) {
	for _, fx := range surfaceFixtures {
		facts, snap := loadFacts(t, fx), testutil.LoadFixture(t, "testdata/fixtures/"+fx)
		got := map[string][2]int{}
		for _, r := range newResults(t, snap, "inspect", "drivers") {
			got[r.Subject] = [2]int{int(r.Details["devices"].(float64)), int(r.Details["nodes"].(float64))}
		}
		if len(got) != len(facts.Drivers) {
			t.Errorf("%s: drivers %d, legacy %d", fx, len(got), len(facts.Drivers))
		}
		for d, want := range facts.Drivers {
			if got[d] != [2]int{want.Devices, len(want.Nodes)} {
				t.Errorf("%s: driver %s devices/nodes %v, legacy %d/%d", fx, d, got[d], want.Devices, len(want.Nodes))
			}
		}
	}
}

func TestParityTopology(t *testing.T) {
	for _, fx := range surfaceFixtures {
		facts, snap := loadFacts(t, fx), testutil.LoadFixture(t, "testdata/fixtures/"+fx)
		type place struct{ numa, root []string }
		got := map[string]place{}
		for _, r := range newResults(t, snap, "inspect", "topology") {
			for _, d := range strs(r.Details["devices"]) {
				got[d] = place{strs(r.Details["numa"]), strs(r.Details["pcieRoot"])}
			}
		}
		if len(got) != len(facts.Topology) {
			t.Errorf("%s: %d devices, legacy %d", fx, len(got), len(facts.Topology))
		}
		for dev, want := range facts.Topology {
			p, ok := got[dev]
			if !ok {
				t.Errorf("%s: device %s missing", fx, dev)
				continue
			}
			if !slices.Contains(p.numa, want.PrimaryNuma) {
				t.Errorf("%s: %s NUMA %v lacks legacy NUMA %s", fx, dev, p.numa, want.PrimaryNuma)
			}
			wr := slices.Clone(want.PcieRoots)
			slices.Sort(wr)
			if !slices.Equal(slices.Sorted(slices.Values(p.root)), wr) {
				t.Errorf("%s: %s pcieRoot %v, legacy %v", fx, dev, p.root, wr)
			}
		}
	}
}

func TestParityClaims(t *testing.T) {
	for _, fx := range surfaceFixtures {
		facts, snap := loadFacts(t, fx), testutil.LoadFixture(t, "testdata/fixtures/"+fx)
		got := map[string][]string{}
		for _, r := range newResults(t, snap, "inspect", "claims") {
			devs := []string{}
			for _, x := range r.Details["results"].([]any) {
				devs = append(devs, x.(map[string]any)["device"].(string))
			}
			slices.Sort(devs)
			got[r.Subject] = devs
		}
		if len(got) != len(facts.Claims) {
			t.Errorf("%s: %d claims, legacy %d", fx, len(got), len(facts.Claims))
		}
		for name, want := range facts.Claims {
			if !slices.Equal(got[name], append([]string{}, want...)) {
				t.Errorf("%s: claim %s devices %v, legacy %v", fx, name, got[name], want)
			}
		}
	}
}

func TestParityAlignment(t *testing.T) {
	for _, fx := range surfaceFixtures {
		facts, snap := loadFacts(t, fx), testutil.LoadFixture(t, "testdata/fixtures/"+fx)
		byClaim := map[string]jsonResult{}
		for _, r := range newResults(t, snap, "check", "alignment") {
			byClaim[r.Subject] = r
		}
		for pod, want := range facts.Alignment {
			ns, name, _ := strings.Cut(pod, "/")
			var devs []string
			var numaAligned, rootAligned bool
			for _, c := range snap.ResourceClaims {
				if c.Namespace != ns || len(c.Status.ReservedFor) == 0 || c.Status.ReservedFor[0].Name != name {
					continue
				}
				r, ok := byClaim[ns+"/"+c.Name]
				if !ok {
					t.Fatalf("%s: no alignment result for claim %s/%s", fx, ns, c.Name)
				}
				for _, d := range strs(r.Details["devices"]) {
					devs = append(devs, d[strings.LastIndex(d, "/")+1:])
				}
				numaAligned, rootAligned = alignedOf(r.Details["numa"]), alignedOf(r.Details["pcieRoot"])
			}
			slices.Sort(devs)
			if !slices.Equal(devs, want.Devices) {
				t.Errorf("%s: pod %s devices %v, legacy %v", fx, pod, devs, want.Devices)
			}
			if numaAligned != (want.Numa == "aligned") {
				t.Errorf("%s: pod %s numa aligned=%v, legacy %q", fx, pod, numaAligned, want.Numa)
			}
			if rootAligned != (want.PcieRoot == "aligned") {
				t.Errorf("%s: pod %s pcieRoot aligned=%v, legacy %q", fx, pod, rootAligned, want.PcieRoot)
			}
		}
	}
}

// alignedOf reads details.<dim>.aligned; dra-inspect omits the section for a
// claim with fewer than two devices, which is trivially aligned (legacy agrees).
func alignedOf(v any) bool {
	m, ok := v.(map[string]any)
	return !ok || m["aligned"].(bool)
}

func TestParityDeviceClasses(t *testing.T) {
	for _, fx := range surfaceFixtures {
		facts, snap := loadFacts(t, fx), testutil.LoadFixture(t, "testdata/fixtures/"+fx)
		got := []string{}
		for _, r := range newResults(t, snap, "inspect", "deviceclasses", "--selector", "nodepartition.dra.k8s.io/managed=true") {
			got = append(got, r.Subject)
		}
		slices.Sort(got)
		if !slices.Equal(got, append([]string{}, facts.DeviceClassesQueried...)) {
			t.Errorf("%s: classes %d, legacy query served %d", fx, len(got), len(facts.DeviceClassesQueried))
		}
	}
}

func TestParityCounters(t *testing.T) {
	for _, name := range []string{"exactly-full", "fits", "none", "overcommit", "stale-generation", "unknown-counter", "unknown-set"} {
		facts := loadFacts(t, "counters-"+name)
		snap := testutil.LoadFixture(t, "testdata/fixtures/counters/"+name)
		got := map[string]map[string]string{}
		for _, r := range newResults(t, snap, "check", "counters") {
			cs, ok := r.Details["counters"].(map[string]any)
			if !ok {
				continue
			}
			set := r.Details["counterSet"].(string)
			got[set] = map[string]string{}
			for c, v := range cs {
				m := v.(map[string]any)
				got[set][c] = m["remaining"].(string) + "/" + m["capacity"].(string)
			}
		}
		for set, counters := range facts.CountersReserved.Sets {
			for c, want := range counters {
				// stale-generation: legacy also reads the superseded slice, so it
				// sees both devices; dra-inspect uses the current generation.
				if name == "stale-generation" {
					want = "2/2"
				}
				if strings.HasPrefix(want, "?") {
					// Legacy cannot compute it (unknown counter); dra-inspect
					// must report that as a failed check instead of a guess.
					if name != "unknown-counter" {
						t.Errorf("%s: unexpected indeterminate legacy value %q", name, want)
					}
					continue
				}
				if got[set][c] != want {
					t.Errorf("%s: %s %s remaining/total %q, legacy %q", name, set, c, got[set][c], want)
				}
			}
		}
	}
}
